const nilaiSiswa = [75, 80, 65, 90, 85];

// Mengubah nilai kedua menjadi 88
nilaiSiswa[1] = 88;

// Mengubah nilai ketiga menjadi 78
nilaiSiswa[2] = 78;

// Menampilkan seluruh Array setelah perubahan
console.log("Nilai siswa setelah diubah:", nilaiSiswa);

// Menampilkan nilai pertama
console.log("Nilai pertama:", nilaiSiswa[0]);

// Menampilkan nilai terakhir
console.log("Nilai terakhir:", nilaiSiswa[nilaiSiswa.length - 1]);